function backupView(mode){
  const days=['日','月','火','水','木'];
  const changes=['FULL','A','B','C','D'];
  const full=days.map((d,i)=>`<div class="backup-day"><b>${d}</b>${i===0?'<div class="backup-block backup-full">フル</div>':'<div class="backup-block backup-inc">変更 '+changes[i]+'</div>'}</div>`).join('');
  if(mode==='full') return `<div class="backup-strip">${full}</div><div class="lesson-copy" style="margin-top:13px">日曜に全データを保存し、月曜以降にA〜Dの変更が発生したとします。</div>`;
  if(mode==='incremental') return `<div class="backup-strip">${days.map((d,i)=>`<div class="backup-day"><b>${d}</b>${i===0?'<div class="backup-block backup-full">フル</div>':`<div class="backup-block backup-inc">${changes[i]}のみ</div>`}</div>`).join('')}</div><div class="lesson-copy" style="margin-top:13px">増分：前回バックアップ以降の変更だけ。</div>`;
  if(mode==='differential') return `<div class="backup-strip">${days.map((d,i)=>`<div class="backup-day"><b>${d}</b>${i===0?'<div class="backup-block backup-full">フル</div>':`<div class="backup-block backup-diff">${changes.slice(1,i+1).join('+')}</div>`}</div>`).join('')}</div><div class="lesson-copy" style="margin-top:13px">差分：直近のフル以降の変更を毎回まとめて保存。</div>`;
