functions.finalizeProfileRecovery:
async function finalizeProfileRecovery(){
  if(profileRecoveryNeedsIndexedDb){
    const recovered=await recoverLatestIndexedDbCheckpoint();
    if(recovered){
      showAppNotice('update','長期保護の復旧点から復元しました','通常データと直前スナップショットの両方が使えなかったため、端末内の長期復旧点から学習データを戻しました。','再読み込み',()=>location.reload());
      setTimeout(()=>location.reload(),900);
      return;
    }
    // No valid long-term checkpoint exists. The original broken raw data remains in CORRUPT_PROFILE_KEY.
    profileWriteBlocked=false;
    profileRecoveryNeedsIndexedDb=false;
    saveProfile();
  }

  if(!profileRecoveryWarning)return;
  if(profileRecoverySource==='snapshot'){
    setTimeout(()=>showAppNotice('update','学習データを自動復旧しました','現在データの整合性に問題が見つかったため、一つ前の正常なスナップショットから復旧しました。破損した元データも復旧用として端末内に退避しています。','データを確認',()=>{showScreen('plan');setTimeout(()=>document.getElementById('pwaHealthCard')?.scrollIntoView?.({behavior:'smooth',block:'center'}),80)}),300);
  }else if(profileRecoverySource==='future'){
    setTimeout(()=>showAppNotice('error','FE QUESTの更新が必要です',`保存データはこのアプリより新しい形式です。上書きを防ぐため学習データへの保存を停止しています。${profileRecoveryReason?`\n${profileRecoveryReason}`:''}`,'更新を確認',()=>checkForAppUpdate(true)),300);
  }else if(profileRecoverySource!=='indexeddb'){
    setTimeout(()=>showAppNotice('error','学習データを読み取れませんでした','正常なローカルスナップショットや長期復旧点も利用できなかったため、新規状態で起動しました。破損した元データは復旧用として端末内に退避しています。','設定を開く',()=>{showScreen('plan');setTimeout(()=>document.getElementById('pwaHealthCard')?.scrollIntoView?.({behavior:'smooth',block:'center'}),80)}),300);
  }
}

functions.getRecoveryCandidate:
async function getRecoveryCandidate(kind,id){
  if(kind==='last-good'){
    const raw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);if(!raw)throw new Error('一世代前のデータがありません');
    return validRawWithChecksum(raw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null).profile;
  }
  const rows=await recoverySnapshots();
  const row=rows.find(x=>String(x.id)===String(id));if(!row)throw new Error('復旧点が見つかりません');
  return decodeBackupPayload(row.payload).profile;
}

functions.importLearningDataFile:
async function importLearningDataFile(file){
  try{
    if(file?.size>5*1024*1024)throw new Error('バックアップファイルが大きすぎます');
    const parsed=JSON.parse(await file.text());
    const decoded=decodeBackupPayload(parsed);
    const message=`現在の学習データを、次のバックアップで置き換えますか？\n\n${backupSummary(decoded)}\n\n現在のデータは端末内に一時退避され、あとから1回だけ戻せます。`;
    if(!confirm(message))return;

    const current=localStorage.getItem(STORAGE_KEY)||JSON.stringify(normalizeProfileData(profile));
    localStorage.setItem(PRE_IMPORT_PROFILE_KEY,current);
    if(!profileWriteBlocked)queueRecoveryCheckpoint('pre-import',true);

    profileWriteBlocked=false;
    profileRecoveryNeedsIndexedDb=false;
    profile=stampProfileForSave(decoded.profile);
    const importedResult=writeCurrentProfile(profile,{preservePrevious:true,skipConflictCheck:true});
    profile=importedResult.profile;rememberCommittedProfile(profile);
    profileConflictBlocked=false;profileConflictNoticeShown=false;
    queueRecoveryCheckpoint('import',true);
    localStorage.removeItem('fequest_bfinal_resume_v1');
    localStorage.removeItem('fequest_ui_state_v2');

    popToast('学習データを読み込みました');setTimeout(()=>location.reload(),500);
  }catch(e){
    console.warn('Import failed',e);
    showAppNotice('error','学習データを読み込めませんでした',e?.message||'FE QUESTのバックアップファイルか確認してください。');
  }
}

functions.loadProfile:
function loadProfile(){
  recoverInterruptedMigrationIfNeeded();

  const atomicRaw=localStorage.getItem(PROFILE_ATOMIC_KEY);
  if(atomicRaw){
    try{
      const a=decodeAtomicProfileEnvelope(atomicRaw);
      profileBaseRevision=a.revision;
      repairCompatibilityMirror(a.profile);
      return a.profile;
    }catch(e){
      console.warn('Atomic profile could not be used; checking compatibility mirror',e);
      if(e?.code==='FUTURE_PROFILE_SCHEMA'){
        profileRecoveryWarning=true;profileRecoveryReason=e?.message||String(e);profileRecoverySource='future';profileWriteBlocked=true;
        return structuredClone(DEFAULT_PROFILE);
      }
      try{localStorage.setItem(CORRUPT_PROFILE_KEY,atomicRaw)}catch(_e){}
    }
  }

  let raw=localStorage.getItem(STORAGE_KEY);
  if(!raw){
    for(const key of LEGACY_STORAGE_KEYS){
      const legacy=localStorage.getItem(key);if(!legacy)continue;
      try{
        const parsed=JSON.parse(legacy),sourceSchema=profileSchemaNumber(parsed);
        let migrated=normalizeProfileData(parsed);
        migrated.profileMeta={...safeObject(migrated.profileMeta),lastAppVersion:APP_VERSION};
        beginMigrationJournal(legacy,null,sourceSchema);
        const result=writeCurrentProfile(migrated,{preservePrevious:false,skipConflictCheck:true});
        finishMigrationJournal();profileRecoverySource='legacy';return result.profile;
      }catch(_e){}
    }
    profileBaseRevision=0;return structuredClone(DEFAULT_PROFILE);
  }

  try{
    const parsed=JSON.parse(raw);
    if(!isPlainObject(parsed))throw new Error('profile is not an object');
    const sourceSchema=profileSchemaNumber(parsed);
    if(sourceSchema>PROFILE_SCHEMA_VERSION)throw futureSchemaError(sourceSchema);
    const expected=localStorage.getItem(PROFILE_CHECKSUM_KEY);
    const sourceChecksum=profileChecksumForSchema(parsed,sourceSchema);
    if(expected&&expected!==sourceChecksum)throw new Error('profile checksum mismatch');
    let p=normalizeProfileData(parsed);

    if(sourceSchema<PROFILE_SCHEMA_VERSION){
      beginMigrationJournal(raw,expected||sourceChecksum,sourceSchema);
      p.profileMeta={...safeObject(p.profileMeta),lastAppVersion:APP_VERSION};
      const migrated=writeCurrentProfile(p,{preservePrevious:true,skipConflictCheck:true});
      p=migrated.profile;finishMigrationJournal();profileRecoverySource='migration';
    }else{
      profileBaseRevision=nonNegativeInt(p.profileMeta?.revision,0);
      repairAtomicEnvelopeExact(p);
      if(!expected)try{localStorage.setItem(PROFILE_CHECKSUM_KEY,profileIntegrityChecksum(p))}catch(_e){}
      if(!localStorage.getItem(LAST_GOOD_PROFILE_KEY))try{localStorage.setItem(LAST_GOOD_PROFILE_KEY,raw);localStorage.setItem(LAST_GOOD_CHECKSUM_KEY,sourceChecksum)}catch(_e){}
    }
    return p;
  }catch(e){
    console.warn('学習データの読み込みに失敗しました。',e);
    profileRecoveryWarning=true;profileRecoveryReason=e?.message||String(e);
    if(e?.code==='FUTURE_PROFILE_SCHEMA'){
      profileRecoverySource='future';profileWriteBlocked=true;return structuredClone(DEFAULT_PROFILE);
    }
    try{localStorage.setItem(CORRUPT_PROFILE_KEY,raw)}catch(_e){}
    const snapshot=localStorage.getItem(LAST_GOOD_PROFILE_KEY);
    if(snapshot){
      try{
        const checked=validRawWithChecksum(snapshot,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null);
        profileRecoverySource='snapshot';
        const result=writeCurrentProfile(checked.profile,{preservePrevious:false,skipConflictCheck:true});
        return result.profile;
      }catch(_e){}
    }
    profileRecoverySource='default';profileRecoveryNeedsIndexedDb=true;profileWriteBlocked=true;profileBaseRevision=0;
    return structuredClone(DEFAULT_PROFILE);
  }
}

