functions.openRecoveryDb:
function openRecoveryDb(){
  if(typeof indexedDB==='undefined')return Promise.reject(new Error('IndexedDB unsupported'));
  return new Promise((resolve,reject)=>{
    const req=indexedDB.open(RECOVERY_DB_NAME,RECOVERY_DB_VERSION);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains(RECOVERY_DB_STORE))db.createObjectStore(RECOVERY_DB_STORE,{keyPath:'id'});
    };
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error||new Error('IndexedDB open failed'));
  });
}

functions.parseProfileRaw:
function parseProfileRaw(raw){
  if(typeof raw!=='string'||!raw.trim())throw new Error('empty profile');
  const parsed=JSON.parse(raw);
  if(!isPlainObject(parsed))throw new Error('profile is not an object');
  if(profileSchemaNumber(parsed)>PROFILE_SCHEMA_VERSION)throw futureSchemaError(profileSchemaNumber(parsed));
  return normalizeProfileData(parsed);
}

functions.performLearningDataResetV333:
async function performLearningDataResetV333(){
  if(profileWriteBlocked||profileConflictBlocked){
    return {ok:false,reason:'blocked'};
  }
  if(!acquireProfileWriteLease()){
    markProfileConflict('別のFE QUEST画面がいま学習データを書き込んでいます');
    return {ok:false,reason:'lease'};
  }

  let result=null;
  let recoveryPointCreated=false;
  try{
    // Keep one explicit recovery-center checkpoint for accidental reset recovery.
    // It is never restored automatically; the learner must deliberately choose it.
    recoveryPointCreated=await createPreResetRecoveryPointV333();

    const next=stampProfileForSave(resetLearningProfileCandidateV333());
    result=writeCurrentProfile(next,{preservePrevious:false,skipConflictCheck:true});
    profile=result.profile;

    // An explicit reset must not leave the old profile as the automatic last-good fallback.
    try{
      localStorage.removeItem(LAST_GOOD_PROFILE_KEY);
      localStorage.removeItem(LAST_GOOD_CHECKSUM_KEY);
      localStorage.setItem(LAST_GOOD_PROFILE_KEY,result.raw);
      localStorage.setItem(LAST_GOOD_CHECKSUM_KEY,result.checksum);
    }catch(e){
      try{localStorage.removeItem(LAST_GOOD_PROFILE_KEY);localStorage.removeItem(LAST_GOOD_CHECKSUM_KEY)}catch(_e){}
      console.warn('Reset last-good mirror could not be refreshed',e);
    }

    clearTransientLearningStateV333();
    rememberCommittedProfile(profile);
    clearProfileSaveFailure();
  }catch(e){
    restoreCommittedProfileInMemory(false);
    noteProfileSaveFailure(e);
    console.warn('FE QUESTの初期化に失敗しました。',e);
    return {ok:false,reason:'write',error:String(e?.message||e)};
  }finally{
    releaseProfileWriteLease();
  }

  try{queueRecoveryCheckpoint('manual-reset',true)}catch(e){console.warn('Reset checkpoint queue failed',e)}
  return {
    ok:true,
    profile:structuredClone(profile),
    settings:structuredClone(profile.settings||{}),
    recoveryPointCreated
  };
}

functions.persistProfileSilently:
function persistProfileSilently(){
  if(!appBootComplete){bootProfileSavePending=true;return true;}
  if(profileWriteBlocked||profileConflictBlocked){restoreCommittedProfileInMemory(false);return false;}
  try{if(profileCommittedChecksum&&profileIntegrityChecksum(profile)===profileCommittedChecksum)return true}catch(_e){}
  if(!acquireProfileWriteLease()){restoreCommittedProfileInMemory(false);return false;}
  let saved=false;
  try{
    profile=stampProfileForSave(profile);
    const result=writeCurrentProfile(profile,{preservePrevious:true});
    profile=result.profile;rememberCommittedProfile(profile);clearProfileSaveFailure();
    saved=true;
  }catch(e){
    restoreCommittedProfileInMemory(false);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT')markProfileConflict();
    else{profileWriteBlocked=true;console.warn('silent save failed',e);setTimeout(()=>refreshPwaHealth?.(),0);}
    return false;
  }finally{releaseProfileWriteLease()}
  try{queueRecoveryCheckpoint('autosave',false)}catch(e){console.warn('Recovery checkpoint queue failed',e)}
  return saved;
}

