functions.queueRecoveryCheckpoint:
function queueRecoveryCheckpoint(reason='autosave',force=false){
  if(profileWriteBlocked||profileConflictBlocked||typeof indexedDB==='undefined')return;
  const now=Date.now();
  if(!force&&now-recoveryCheckpointLastAt<RECOVERY_CHECKPOINT_INTERVAL)return;
  setTimeout(()=>writeRecoveryCheckpoint(profile,reason,force).then(ok=>{if(ok)refreshPwaHealth?.();}).catch(e=>console.warn('Recovery checkpoint failed',e)),0);
}

functions.quickProfileIntegrityState:
function quickProfileIntegrityState(){
  try{
    const a=currentAtomicProfile();
    if(!a)return {ok:false,label:'初回保存前'};
    const mirror=localStorage.getItem(STORAGE_KEY);
    const expected=localStorage.getItem(PROFILE_CHECKSUM_KEY);
    if(!mirror)return {ok:false,label:'ミラー未作成'};
    const checked=validRawWithChecksum(mirror,expected||null);
    if(profileIntegrityChecksum(checked.profile)!==profileIntegrityChecksum(a.profile))return {ok:false,label:'ミラー差異'};
    return {ok:true,label:'正常'};
  }catch(e){return {ok:false,label:'要確認',error:e};}
}

functions.recoverInterruptedMigrationIfNeeded:
function recoverInterruptedMigrationIfNeeded(){
  const jr=localStorage.getItem(PROFILE_MIGRATION_JOURNAL_KEY);if(!jr)return false;
  try{
    const atomic=currentAtomicProfile();
    if(atomic&&atomic.sourceSchema===PROFILE_SCHEMA_VERSION){finishMigrationJournal();return false}
  }catch(_e){}
  try{
    const j=JSON.parse(jr);
    if(j?.format==='fequest-migration-v1'&&typeof j.raw==='string'){
      const checked=validRawWithChecksum(j.raw,j.checksum||null);
      if(checked.sourceSchema<=PROFILE_SCHEMA_VERSION){
        localStorage.setItem(STORAGE_KEY,j.raw);
        if(j.checksum)localStorage.setItem(PROFILE_CHECKSUM_KEY,j.checksum);else localStorage.removeItem(PROFILE_CHECKSUM_KEY);
        localStorage.removeItem(PROFILE_ATOMIC_KEY);
      }
    }
  }catch(e){console.warn('Interrupted migration rollback failed',e)}
  finishMigrationJournal();return true;
}

