functions.recoveryProfileMetrics:
function recoveryProfileMetrics(p){
  const qStats=safeObject(p?.qStats);
  const attempted=Object.values(qStats).filter(x=>nonNegativeInt(x?.attempts,0)>0).length;
  const answered=Object.values(qStats).reduce((n,x)=>n+nonNegativeInt(x?.attempts,0),0);
  const lessonDone=Object.values(safeObject(p?.lessonProgress)).filter(x=>Number(x)>=100).length;
  const bDone=Object.values(safeObject(p?.bProgress)).filter(x=>Number(x)>=100).length;
  const secDone=Object.values(safeObject(p?.securityBProgress)).filter(x=>Number(x)>=100).length;
  return {xp:nonNegativeInt(p?.xp,0),lessonDone,bDone,secDone,attempted,answered};
}

functions.recoveryReasonText:
function recoveryReasonText(reason=''){
  if(reason==='manual')return '手動作成';
  if(reason==='autosave')return '自動保護';
  if(reason==='pre-update')return 'アプリ更新前';
  if(reason==='pre-import')return 'バックアップ読込前';
  if(reason==='import')return 'バックアップ読込後';
  if(reason==='pre-import-restore')return '読込前データへの復帰後';
  if(reason==='pre-manual-restore')return '手動復元前';
  if(reason==='manual-restore')return '手動復元後';
  if(reason==='manual-restore-undo')return '手動復元の取消後';
  if(String(reason).startsWith('version-'))return `${String(reason).slice(8)}初回`;
  return reason||'自動保護';
}

functions.recoverySnapshots:
async function recoverySnapshots(){
  const db=await openRecoveryDb();
  try{
    const tx=db.transaction(RECOVERY_DB_STORE,'readonly');
    const rows=await idbRequest(tx.objectStore(RECOVERY_DB_STORE).getAll());
    return (rows||[]).sort((a,b)=>(b.id||0)-(a.id||0));
  }finally{db.close();}
}

functions.rememberCommittedProfile:
function rememberCommittedProfile(p=profile){
  const normalized=normalizeProfileData(p);
  profileCommittedSnapshot=structuredClone(normalized);
  profileCommittedChecksum=profileIntegrityChecksum(normalized);
  profileBaseRevision=nonNegativeInt(normalized.profileMeta?.revision,profileBaseRevision);
  return normalized;
}

functions.renderRecoveryCenter:
async function renderRecoveryCenter(){
  const list=document.getElementById('recoveryPointList'),status=document.getElementById('recoveryCenterStatus'),undo=document.getElementById('restorePreManual'),corrupt=document.getElementById('exportCorruptProfile');
  if(!list||!status)return;
  if(undo)undo.classList.toggle('hidden',!localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY));
  if(corrupt)corrupt.classList.toggle('hidden',!localStorage.getItem(CORRUPT_PROFILE_KEY));
  list.replaceChildren();
  if(profileRecoverySource==='future'){
    status.textContent='保存データがこの画面より新しい形式です。復旧操作はせず、先にFE QUESTを更新してください。';status.className='recovery-center-status warn';return;
  }
  const items=await recoveryCandidates();
  const valid=items.filter(x=>x.valid);
  const currentChecksum=profileIntegrityChecksum(profile);
  const restorable=valid.filter(x=>profileIntegrityChecksum(x.profile)!==currentChecksum);
  status.textContent=restorable.length?`現在：${recoveryMetricsText(profile)}。戻せる過去データが${restorable.length}件あります。通常時は復元する必要はありません。`:'現在と異なる復旧候補はありません。現在データが正常なら、そのまま利用できます。';
  status.className=`recovery-center-status ${valid.length?'good':''}`;
