functions.restorePreImportProfile:
function restorePreImportProfile(){
  const raw=localStorage.getItem(PRE_IMPORT_PROFILE_KEY);
  if(!raw){popToast('戻せる読込前データはありません');return false}
  try{
    const parsed=JSON.parse(raw);
    if(!isPlainObject(parsed))throw new Error('profile is not an object');
    if(!confirm('直前にバックアップを読み込む前の学習データへ戻しますか？'))return false;
    const schema=profileSchemaNumber(parsed);
    if(schema>PROFILE_SCHEMA_VERSION){
      // Exact rollback is more important than forcing a downgrade conversion.
      // Remove the current atomic envelope; otherwise it would remain authoritative on reload
      // and the restored newer-format compatibility mirror would never be reached.
      localStorage.setItem(STORAGE_KEY,raw);
      localStorage.removeItem(PROFILE_CHECKSUM_KEY);
      localStorage.removeItem(PROFILE_ATOMIC_KEY);
    }else{
      const restored=stampProfileForSave(parsed);
      const restoredResult=writeCurrentProfile(restored,{preservePrevious:true,skipConflictCheck:true});
      profile=restoredResult.profile;rememberCommittedProfile(profile);
      queueRecoveryCheckpoint('pre-import-restore',true);
    }
    localStorage.removeItem(PRE_IMPORT_PROFILE_KEY);
    localStorage.removeItem('fequest_bfinal_resume_v1');
    localStorage.removeItem('fequest_ui_state_v2');
    popToast('読込前の学習データへ戻しました');
    setTimeout(()=>location.reload(),500);
    return true;
  }catch(e){
    showAppNotice('error','読込前データを復元できませんでした','退避データが破損している可能性があります。');
    return false;
  }
}

