functions.revalidateProfileFreshness:
function revalidateProfileFreshness(reason='画面復帰'){
  if(profileWriteBlocked||profileConflictBlocked)return false;
  try{
    const atomic=currentAtomicProfile();
    if(!atomic)return true;
    const rev=nonNegativeInt(atomic.revision,0);
    const checksum=atomic.checksum||profileIntegrityChecksum(atomic.profile);
    const externalWriter=atomic.writerId!==TAB_INSTANCE_ID;
    const newer=rev>profileBaseRevision;
    const rewound=rev<profileBaseRevision;
    const sameRevisionChanged=rev===profileBaseRevision&&checksum!==profileCommittedChecksum;
    if((externalWriter&&newer)||rewound||sameRevisionChanged){
      restoreCommittedProfileInMemory(true);
      markProfileConflict(`${reason}時に、別の保存世代を検出しました`);
      return false;
    }
    return true;
  }catch(e){
    if(e?.code==='FUTURE_PROFILE_SCHEMA'){
      restoreCommittedProfileInMemory(true);profileWriteBlocked=true;profileRecoverySource='future';profileRecoveryReason=e?.message||String(e);
      showAppNotice?.('error','FE QUESTの更新が必要です','画面復帰時に、このアプリより新しい形式の学習データを検出しました。上書きを防ぐため保存を停止しています。','更新を確認',()=>checkForAppUpdate(true));
      return false;
    }
    restoreCommittedProfileInMemory(true);markProfileConflict(`${reason}時に保存データの整合性を確認できませんでした`);return false;
  }
}

