decodeAtomicProfileEnvelope.source:
function decodeAtomicProfileEnvelope(raw){
  if(typeof raw!=='string'||!raw.trim())throw new Error('empty atomic profile');
  const env=JSON.parse(raw);
  if(!isPlainObject(env)||env.format!=='fequest-profile-atomic-v1'||!isPlainObject(env.profile))throw new Error('invalid atomic profile');
  const schema=nonNegativeInt(env.profileSchemaVersion??env.profile.profileSchemaVersion,1);
  if(schema>PROFILE_SCHEMA_VERSION)throw futureSchemaError(schema);
  const actual=profileChecksumForSchema(env.profile,schema);
  if(typeof env.checksum!=='string'||actual!==env.checksum)throw new Error('atomic profile checksum mismatch');
  const normalized=normalizeProfileData(env.profile);
  const rev=nonNegativeInt(env.revision??normalized.profileMeta?.revision,0);
  normalized.profileMeta={...safeObject(normalized.profileMeta),revision:rev,lastWriterId:typeof env.writerId==='string'?env.writerId:(normalized.profileMeta?.lastWriterId||null)};
  return {profile:normalized,revision:rev,writerId:normalized.profileMeta.lastWriterId,sourceSchema:schema,checksum:profileIntegrityChecksum(normalized)};
}

decodeBackupPayload.source:
function decodeBackupPayload(parsed){
  if(!isPlainObject(parsed))throw new Error('バックアップの形式が一致しません');
  const candidate=isPlainObject(parsed.profile)?parsed.profile:parsed;
  if(!validateImportedProfile(candidate))throw new Error('学習データとして認識できません');

  const schema=nonNegativeInt(parsed.profileSchemaVersion??candidate.profileSchemaVersion??1,1);
  if(schema>PROFILE_SCHEMA_VERSION)throw new Error('このバックアップは、より新しいFE QUESTで作成されています');

  if(parsed.format==='fequest-backup-v2'){
    if(typeof parsed.checksum!=='string')throw new Error('整合性情報がありません');
    const actual=schema===3?profileIntegrityChecksumV3(candidate):schema===4?profileIntegrityChecksumV4(candidate):profileIntegrityChecksum(candidate);
    if(actual!==parsed.checksum)throw new Error('整合性チェックに失敗しました。ファイルが破損または変更されています');
  }else if(parsed.format && parsed.format!=='fequest-backup-v1'){
    throw new Error('未対応のバックアップ形式です');
  }

  return {
    profile:normalizeProfileData(candidate),
    sourceFormat:parsed.format||'legacy-profile',
    appVersion:typeof parsed.appVersion==='string'?parsed.appVersion:'旧形式',
    exportedAt:typeof parsed.exportedAt==='string'?parsed.exportedAt:null,
    sourceSchema:schema
  };
}

