  if((state.active||0)>0)return `復習ルート ${state.active}件を終えると、習得状態への復帰へ近づきます。`;
  if((state.due||0)>0)return `期限/低保持 ${state.due}問だけを戻します。`;
  if(state.minRetention!=null&&state.minRetention<85)return `最低保持 ${state.minRetention}% の問題を優先して戻します。`;
