recoveryCandidates.source:
function recoveryCandidates(){
  const items=[];
  const lastRaw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);
  if(lastRaw){
    try{
      const checked=validRawWithChecksum(lastRaw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null);
      items.push({kind:'last-good',id:'last-good',label:'一世代前の正常データ',createdAt:checked.profile.profileMeta?.updatedAt||null,reason:'一世代前',profile:checked.profile,valid:true});
    }catch(e){items.push({kind:'last-good',id:'last-good',label:'一世代前のデータ',createdAt:null,reason:'一世代前',valid:false,error:e?.message||String(e)})}
  }
  if(typeof indexedDB!=='undefined'){
    let rows=[];try{rows=await recoverySnapshots()}catch(e){rows=[]}
    for(const row of rows){
      try{
        const decoded=decodeBackupPayload(row.payload);
        items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt||decoded.exportedAt,reason:row.reason,profile:decoded.profile,valid:true});
      }catch(e){items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt,reason:row.reason,valid:false,error:e?.message||String(e)})}
    }
  }
  return items;
}

