recoveryProfileMetrics.source:
function recoveryProfileMetrics(p){
  const qStats=safeObject(p?.qStats);
  const attempted=Object.values(qStats).filter(x=>nonNegativeInt(x?.attempts,0)>0).length;
  const answered=Object.values(qStats).reduce((n,x)=>n+nonNegativeInt(x?.attempts,0),0);
  const lessonDone=Object.values(safeObject(p?.lessonProgress)).filter(x=>Number(x)>=100).length;
  const bDone=Object.values(safeObject(p?.bProgress)).filter(x=>Number(x)>=100).length;
  const secDone=Object.values(safeObject(p?.securityBProgress)).filter(x=>Number(x)>=100).length;
  return {xp:nonNegativeInt(p?.xp,0),lessonDone,bDone,secDone,attempted,answered};
}

recoveryReasonText.source:
function recoveryReasonText(reason=''){
  if(reason==='manual')return '手動作成';
  if(reason==='autosave')return '自動保護';
  if(reason==='pre-update')return 'アプリ更新前';
  if(reason==='pre-import')return 'バックアップ読込前';
  if(reason==='import')return 'バックアップ読込後';
  if(reason==='pre-import-restore')return '読込前データへの復帰後';
  if(reason==='pre-manual-restore')return '手動復元前';
  if(reason==='manual-restore')return '手動復元後';
  if(reason==='manual-restore-undo')return '手動復元の取消後';
  if(String(reason).startsWith('version-'))return `${String(reason).slice(8)}初回`;
  return reason||'自動保護';
}

recoverySnapshots.source:
function recoverySnapshots(){
  const db=await openRecoveryDb();
  try{
    const tx=db.transaction(RECOVERY_DB_STORE,'readonly');
    const rows=await idbRequest(tx.objectStore(RECOVERY_DB_STORE).getAll());
    return (rows||[]).sort((a,b)=>(b.id||0)-(a.id||0));
  }finally{db.close();}
}

