syncMasteryRecoveryHistory.source:
function syncMasteryRecoveryHistory(topicStates){
  profile.masteryHistory=safeObject(profile.masteryHistory);
  let changed=false;
  const today=localDateISO(0);
  (topicStates||[]).forEach(x=>{
    const id=x?.topic?.id;if(!id)return;
    const state=x.state||{};
    const old=isPlainObject(profile.masteryHistory[id])?profile.masteryHistory[id]:{};
    const next={...old};

    if(state.key==='master'){
      if(!next.firstMasteredAt){next.firstMasteredAt=today;changed=true;}
      next.lastMasteredAt=today;
      if(next.recoveryNeeded){
        next.recoveryNeeded=false;
        next.lastRecoveredAt=today;
        next.recoveries=(next.recoveries||0)+1;
        changed=true;
      }
    }else if(next.firstMasteredAt&&next.lastState==='master'&&!next.recoveryNeeded){
      next.recoveryNeeded=true;
      next.lostAt=today;
      changed=true;
    }

    if(next.lastState!==state.key){next.lastState=state.key;changed=true;}
    if(next.lastRetention!==state.retention){next.lastRetention=state.retention??null;changed=true;}
    if(next.lastChapterReady!==!!state.chapterReady){next.lastChapterReady=!!state.chapterReady;changed=true;}
    if(JSON.stringify(old)!==JSON.stringify(next))profile.masteryHistory[id]=next;
  });
  if(changed&&typeof persistProfileSilently==='function')persistProfileSilently();
  return changed;
}

