function verifyProfileDurability(showResult=true){
  if(profileRecoverySource==='future'){
    if(showResult)showAppNotice('error','最新版への更新が必要です','保存データはこの画面より新しい形式です。古い画面では検査や修復を行わず、最新版へ更新してから確認してください。','更新を確認',()=>checkForAppUpdate(true));
