  if(quick.ok){
    if(showResult)showAppNotice('info','学習データは正常です',`原子的な現在データと互換ミラーの整合性を確認しました。長期復旧点は${points}件あります。${localStorage.getItem(LAST_GOOD_PROFILE_KEY)?'一世代前の正常データも保持しています。':'一世代前のデータは次回保存以降に作成されます。'}`);
    return true;
  }
  if(showResult)showAppNotice('error','学習データを確認してください',`整合性確認結果：${quick.label}。現在の確定データは自動復旧機構で保護されていますが、念のため外部バックアップを書き出してください。`,'データを書き出す',exportLearningData);
  return false;
}

writeRecoveryCheckpoint.source:
function writeRecoveryCheckpoint(p=profile,reason='autosave',force=false){
  if(typeof indexedDB==='undefined'||profileWriteBlocked||profileConflictBlocked)return false;
  const now=Date.now();
  if(!force&&now-recoveryCheckpointLastAt<RECOVERY_CHECKPOINT_INTERVAL)return false;
  if(!force&&(await storagePressureRatio())>=0.90)return false;
  recoveryCheckpointLastAt=now;
  const payload=makeBackupPayload(p);
  const db=await openRecoveryDb();
  try{
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(RECOVERY_DB_STORE,'readwrite');
      const store=tx.objectStore(RECOVERY_DB_STORE);
      store.put({id:now,createdAt:new Date(now).toISOString(),reason,appVersion:APP_VERSION,profileSchemaVersion:PROFILE_SCHEMA_VERSION,payload});
      tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB write failed'));tx.onabort=()=>reject(tx.error||new Error('IndexedDB write aborted'));
    });
    const rows=await recoverySnapshots();
    if(rows.length>RECOVERY_MAX_SNAPSHOTS){
      const db2=await openRecoveryDb();
      try{
        await new Promise((resolve,reject)=>{
          const tx=db2.transaction(RECOVERY_DB_STORE,'readwrite'),store=tx.objectStore(RECOVERY_DB_STORE);
          rows.slice(RECOVERY_MAX_SNAPSHOTS).forEach(x=>store.delete(x.id));
          tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB trim failed'));
        });
      }finally{db2.close();}
    }
    return true;
  }finally{db.close();}
}
